import { expect, test } from '@playwright/test';

test('firefox: /api/me returns 200 immediately after refresh', async ({ page }) => {
  await page.goto('/dashboard');
  await page.evaluate(() => localStorage.setItem('auth.token', 'valid-test-token'));
  await page.reload();
  const res = await page.waitForResponse((r) => r.url().endsWith('/api/me'));
  expect(res.status()).toBe(200);
});
